class stringx
{
public:
  const char* c_str() const;
};

stringx operator+(const stringx&, const char*);
stringx operator+(const stringx&, const stringx&);
void error(const stringx&);

class script_executable
{
public:
  const stringx& get_fullname() const;
};

class script_instance
{
public:
  const stringx& get_name() const;
};

class vm_thread
{
public:
  script_instance* get_instance() const;
  script_executable* get_executable() const;
};

class vm_stack
{
public:
  int salloc;
  char* buffer;
  char* SP;
  vm_thread* my_thread;

  char* get_SP() const { return SP; }
  vm_thread* get_thread() const { return my_thread; }
  void pop(int n) { SP -= n; }
  bool push(const char* src, int n);
};

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t { FIRST_ENTRY };
  };
};

class widget
{
public:
  enum rhw_layer_e { RHW0 };
  static void set_rhw_2d_layer(rhw_layer_e);
  static void restore_last_rhw_2d_layer();
};

class bitmap_widget : public widget
{
public:
  bitmap_widget(const char*, widget*, short, short, int = 1);
  bool open(const char*);
};

class game
{
public:
  widget* get_script_widget_holder() const;
};

extern game* g_game_ptr;
typedef const stringx* vm_str_t;
typedef bitmap_widget* vm_bitmap_widget_t;

class slf_create_bitmap_widget_t : public script_library_class::function
{
public:
  struct parms_t
  {
    vm_str_t filename;
  };

  bool operator()(vm_stack& stack, entry_t entry);
};

bool slf_create_bitmap_widget_t::operator()(vm_stack& stack, entry_t entry)
{
  stack.pop(sizeof(parms_t));
  parms_t* parms = (parms_t*)stack.get_SP();

  widget::set_rhw_2d_layer(widget::RHW0);
  vm_bitmap_widget_t result = new bitmap_widget("script bitmap widg", (widget*)(g_game_ptr->get_script_widget_holder()), 0, 0);
  result->open(parms->filename->c_str());
  widget::restore_last_rhw_2d_layer();

  if (!stack.push((char*)&result, sizeof(result)))
    error(stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname());
  return true;
}
